Consider the C function `foo` and the binary tree shown.

![img](https://raw.githubusercontent.com/gecwyd/gate-questions/main/2023/cs/p1/images/p49_Q_47_img_1.png)

```c
typedef struct node {
    int val;
    struct node *left, *right;
} node;

int foo(node *p) {
    int retval;
    if (p == NULL)
        return 0;
    else {
        retval = p->val + foo(p->left) + foo(p->right);
        printf("%d ", retval);
        return retval;
    }
}
```

